ROOT=Path(__file__).resolve().parent; PROJECT=ROOT.parent; BASELINE=PROJECT/'validation'; OUT=PROJECT/'reports'; OUT.mkdir(exist_ok=True)
def read(p):return json.loads(p.read_text())
def rows(name):
 with (ROOT/'results/exports'/name).open() as f:return list(csv.DictReader(f,delimiter='\t'))
def e(x):return html.escape(str(x if x not in ('',None) else 'Not reported'))
def n(x):return f'{int(x):,}'
def pct(a,b):return f'{a/b*100:.1f}%'
def table(headers,records,caption=''):
 return '<div class="table-wrap"><table>'+('<caption>'+e(caption)+'</caption>' if caption else '')+'<thead><tr>'+''.join('<th scope="col">'+e(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(x)+'</td>' for x in r)+'</tr>' for r in records)+'</tbody></table></div>'
def svg(fig,caption):
 out=io.StringIO();fig.savefig(out,format='svg',bbox_inches='tight',facecolor='white');plt.close(fig)
 value=out.getvalue();value=value[value.index('<svg'):]
 figure_names={'Figure 2.':'consequence-spectrum.svg','Figure 3.':'genomic-distribution.svg','Figure 4.':'transcript-sensitivity.svg','Figure 1.':'chromosome-3d-overview.svg','Figure 5.':'chromosome-3d-closeup.svg'}
 opening=value.index('>')+1;value=value[:opening]+'<style>text{font-family:Arial,sans-serif!important}</style>'+value[opening:]
 name=next(name for prefix,name in figure_names.items() if caption.startswith(prefix));(OUT/'figures').mkdir(exist_ok=True);(OUT/'figures'/name).write_text(value)
 return '<figure>'+value+'<figcaption>'+e(caption)+'</figcaption></figure>'
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.labelcolor':'#263d50','text.color':'#263d50','axes.edgecolor':'#a8b8c4','svg.fonttype':'none','svg.hashsalt':'vep-experiment-report-v1'})
data=read(ROOT/'report/assets/dataset.json');m=data['metrics'];snap=read(ROOT/'results/snapshot.json');clinical=read(ROOT/'results/clinvar-overlay.json');cases=data['cases'];baseline_manifest=read(BASELINE/'results/run-manifest.json');baseline_cases=read(BASELINE/'results/case-studies.json');spectrum=rows('consequence-spectrum.tsv');pairs=rows('transcript-selection.tsv');genes=rows('gene-summary.tsv');bins=data['bins'];cv=rows('clinvar-matches.tsv');tx=rows('transcripts.tsv')
allele_counts=collections.Counter()
for row in spectrum:
 if row['unit']=='alleles':allele_counts[row['term']]+=int(row['count'])
assert sum(allele_counts.values())==m['input_alleles']==1307
assert len(tx)==m['transcript_rows'];assert sum(b['alleles'] for b in bins)==1307
# Standard scientific plotting, with embedded SVG for portable, vector-quality output.
fig,ax=plt.subplots(figsize=(9,6.4));items=allele_counts.most_common();terms=[x[0].replace('_',' ') for x in items];counts=[x[1] for x in items];ax.barh(range(len(items)),counts,color='#347f89');ax.set_yticks(range(len(items)),terms);ax.invert_yaxis();ax.set_xlabel('Distinct HG002 alleles (one provider summary per allele)');ax.set_xlim(0,max(counts)*1.15)
for i,v in enumerate(counts):ax.text(v+max(counts)*.012,i,str(v),va='center',fontsize=9)
fig.tight_layout();spectrum_fig=svg(fig,'Figure 2. Observed allele-level consequence spectrum. Each of the 1,307 alleles appears once, using VEP’s provider-level most-severe label across all reported features. Small counts are labelled explicitly. These labels are not clinical classifications.')
x=[(b['start_0based']+b['end_0based_exclusive'])/2/1e6 for b in bins]
fig,axes=plt.subplots(3,1,figsize=(9,7),sharex=True,gridspec_kw={'height_ratios':[2,1,1.4]})
axes[0].bar(x,[b['alleles'] for b in bins],width=.021,color='#347f89');axes[0].set_ylabel('Distinct alleles')
axes[1].bar(x,[b['high_confidence_bases']/25000*100 for b in bins],width=.021,color='#8194a5');axes[1].set_ylabel('HC coverage (%)');axes[1].set_ylim(0,105)
axes[2].plot(x,[b['alleles_per_million_hc_bases'] for b in bins],color='#9b6d27',marker='o',markersize=3);axes[2].set_ylabel('Alleles / million\nHC bases');axes[2].set_xlabel('GRCh38 chromosome 9 position (Mb)');axes[2].set_xlim(128,129)
for ax in axes:ax.grid(axis='y',alpha=.16);ax.ticklabel_format(axis='x',style='plain',useOffset=False)
fig.tight_layout();distribution_fig=svg(fig,'Figure 3. Distribution in forty fixed 25 kb windows. The middle track shows high-confidence (HC) benchmark coverage, rather than assuming all bases were analyzed equally. Rates divide the allele count by the high-confidence bases in each window. Differences are descriptive and do not identify disease hotspots.')
fig,axes=plt.subplots(1,2,figsize=(9,2.7));values=[(m['pairs_differing'],m['allele_gene_pairs']-m['pairs_differing']),(m['pairs_selected_misses_more_severe'],m['allele_gene_pairs']-m['pairs_selected_misses_more_severe'])]
for ax,(yes,no),title in zip(axes,values,['Consequences differ across transcripts','Representative omits a more severe term']):
 ax.barh([0],[yes],color='#347f89',label='Yes');ax.barh([0],[no],left=[yes],color='#dfe7ed',label='No');ax.set_yticks([]);ax.set_xlim(0,m['allele_gene_pairs']);ax.set_xlabel('Allele–gene pairs (denominator 2,170)');ax.set_title(title,fontsize=10);ax.text(0,.32,f'Yes: {yes:,} ({pct(yes,m["allele_gene_pairs"])})',fontsize=10);ax.legend(loc='lower center',bbox_to_anchor=(.5,-.65),ncol=2,frameon=False)
fig.tight_layout();sensitivity_fig=svg(fig,'Figure 4. Two separate comparisons, each with 2,170 allele–gene pairs as its denominator. The bars are not disjoint categories to be added together. “More severe” follows the pinned Ensembl molecular-consequence ranking; it is not a measure of clinical pathogenicity.')
# Static 3D figures use the same saved bins and class mapping as the browser.
classes=sorted({a['consequence_class'] for a in data['alleles']})
def make_3d(selected_bins,title,caption,labels=False):
 fig=plt.figure(figsize=(10.5,7.3));ax=fig.add_subplot(111,projection='3d')
 total=0
 for b in selected_bins:
  groups=collections.Counter()
  for term,count in b['terms'].items():groups[data['term_classes'][term]]+=count
  for category,count in groups.items():
   x0=b['start_0based']/1e6;y0=classes.index(category);total+=count
   ax.bar3d(x0+.003,y0-.32,0,.019,.64,count,color='#428993',edgecolor='#2a6873',linewidth=.2,shade=True,alpha=.96)
   if labels:ax.text(x0+.0125,y0,count+.5,str(count),ha='center',va='bottom',fontsize=8,color='#203345')
 xmin=selected_bins[0]['start_0based']/1e6;xmax=selected_bins[-1]['end_0based_exclusive']/1e6
 ax.set_xlim(xmin,xmax);ax.set_ylim(-.6,len(classes)-.4);ax.set_yticks(range(len(classes)),classes,fontsize=8)
 ax.set_xticks([xmin+(xmax-xmin)*i/4 for i in range(5)]);ax.ticklabel_format(axis='x',style='plain',useOffset=False)
 ax.set_xlabel('GRCh38 chromosome 9 position (Mb)',labelpad=13,fontsize=10);ax.set_ylabel('Consequence class',labelpad=20,fontsize=10);ax.set_zlabel('Distinct allele count',labelpad=8,fontsize=10)
 ax.tick_params(axis='x',labelsize=8,pad=1);ax.tick_params(axis='y',pad=2);ax.tick_params(axis='z',labelsize=8)
 ax.text2D(.78,.92,'Z: distinct allele count',transform=ax.transAxes,fontsize=10,color='#263d50');ax.view_init(elev=27,azim=-58);ax.set_box_aspect((1.7,1.1,.9));ax.set_title(title,loc='left',fontsize=13,pad=14)
 for axis in [ax.xaxis,ax.yaxis,ax.zaxis]:axis.set_pane_color((.96,.98,.99,1))
 fig.subplots_adjust(left=.02,right=.9,bottom=.09,top=.92)
 return svg(fig,caption),total
overview_3d,total_3d=make_3d(bins,'Chromosome position × consequence class × allele count','Figure 1. Static 3D overview of the completed 1 Mb pilot. X is GRCh38 position in megabases, Y is a grouped provider-summary consequence class, and Z is the number of distinct alleles in each 25 kb window/class. Each allele contributes once; the bars sum to 1,307. Shading helps show geometry and does not encode clinical risk. Use Figures 2–3 and the tables for exact comparisons.')
assert total_3d==m['input_alleles']
zoom_bins=[b for b in bins if 128250000<=b['start_0based']<128350000]
zoom_total=sum(b['alleles'] for b in zoom_bins)
zoom_3d,zoom_check=make_3d(zoom_bins,'Closer view: chr9:128,250,001–128,350,000',f'Figure 5. Static 3D close-up of four existing 25 kb windows around the GOLGA2 and COQ4 case-study region. These bars contain {zoom_total} distinct alleles already included in the full pilot, not additional samples or a new annotation run. Nonzero bars are labelled with their exact counts. The vertical scale differs from Figure 1; compare values, not apparent heights across figures.',labels=True)
assert zoom_check==zoom_total
class_counts=collections.Counter(h['classification_summary'] for h in cv);review_counts=collections.Counter(h['review_status'] for h in cv);tier_counts=collections.Counter(p['selection_tier'] for p in pairs)
body='''<section class="cover"><p class="eyebrow">Reproducible genomics project · experiment report</p><h1>HG002 Chromosome 9<br>Variant Annotation</h1><p class="subtitle">How transcript choice changes the predicted effect of a DNA variant</p><p class="scope">Educational analysis of public training variants and the HG002 benchmark sample</p><div class="cover-rule"></div><p><strong>Completed experimental scope</strong><br>Training validation: five Ensembl teaching variants.<br>HG002 analysis: GRCh38 chromosome 9, bases 128,000,001–129,000,000.</p><p><strong>Important scope boundary</strong><br>The expanded experiment covers one million bases, not the whole chromosome. Whole-chromosome offline annotation remains blocked by local infrastructure.</p><p class="small">Based on authentic Ensembl release 116 annotations acquired on 17 November 2026, GIAB HG002 NIST v4.2.1 benchmark calls, and ClinVar GRCh38 release 2026-11-08. No patient metadata or private samples were used.</p></section>'''
body+='<section class="front-3d"><p class="eyebrow">Results at a glance</p><h2>1,307 DNA changes across a one-million-base interval</h2><p>This overview combines genomic location, predicted consequence class and allele count. The tallest bars indicate more observed alleles; they do not indicate greater disease risk. The analysis covers only the declared HG002 interval.</p>'+overview_3d+'</section>'
body+='''<section><h2>Executive summary</h2><p>This project investigates a practical problem in variant annotation: <strong>the same DNA change can receive different predicted effects when interpreted against different transcripts of a gene</strong>. A transcript is an RNA version produced from a gene. Different versions can use different exons, coding boundaries or splice sites, so the location and predicted effect of one variant can change with the transcript model.</p><p>The work began with five public Ensembl training examples and expanded to a preselected one-million-base interval from HG002, a public benchmark sample. Existing variant calls were checked against GRCh38, normalized, annotated using genuine Ensembl VEP results, analyzed across all reported transcripts, and presented in reproducible exports and local reports.</p>'''
body+=table(['Main finding','Observed result','Why it matters'],[['Authentic expanded dataset','1,307 eligible alleles; 38,589 transcript annotations','A single allele can generate many annotations; these units must stay separate.'],['Transcript sensitivity','1,081 of 2,170 allele–gene pairs have different consequence sets','Collapsing a variant to one transcript can hide real annotation differences.'],['Representative versus all transcripts','183 of 2,170 pairs select a transcript without another transcript’s more severe term','A standard representative improves consistency but is not a substitute for reviewing transcript context.'],['Dated clinical-source overlap','116 exact eligible ClinVar matches; 1,191 unmatched','An overlap supplies source assertions to inspect, not an automatically established clinical interpretation.'],['Completed coverage','1 Mb interval; 886,920 high-confidence bases','Findings apply to this selected benchmark interval, not to a population or the whole genome.']])
body+='''<p class="callout">The central result is a distinction between <strong>molecular annotation</strong> and <strong>clinical significance</strong>. VEP predicts transcript-dependent molecular consequences. Clinical assessment needs additional, condition-specific evidence, and a dated database assertion must be examined in context.</p></section>'''
chapters=[('question','1. Purpose and scientific question'),('basics','2. Reading the terminology'),('validation','3. Training validation: establishing the baseline'),('methods','4. HG002 analysis: process and quality control'),('results','5. Expanded results and their meaning'),('cases','6. Four cases explained'),('clinical','7. Dated clinical evidence overlay'),('software','8. Software, explorer and reproducibility'),('limits','9. Limitations and work not completed'),('future','10. Future work and decision gates'),('conclusion','11. Conclusions'),('appendix','Appendix: numerical evidence and provenance'),('sources','Sources')]
body+='<nav aria-label="Report contents"><h2>Contents</h2><ol>'+''.join(f'<li><a href="#{key}">{e(label)}</a></li>' for key,label in chapters)+'</ol></nav>'
body+='''<section id="question"><h2>1. Purpose and scientific question</h2><p><strong>Research question:</strong> how do predicted consequences differ across transcripts, and what evidence would be needed to assess clinical significance?</p><p>The experiment does not begin with sequencing reads. It begins with already-called variants: a teaching set in Training validation and an established public benchmark callset in HG002 analysis. The task is to annotate and compare those supplied calls. No variant-calling accuracy, precision or recall is estimated because there is no independent query callset being benchmarked against truth.</p><p>The objective is both analytical and practical: preserve an auditable route from input allele to raw annotation, transcript-level export, representative-transcript decision and the explanation presented to a reader. Every numerical headline can be reconciled with saved exports. The browser explorer and this report communicate the same experiment at different levels of detail.</p><h3>Why this question matters</h3><p>A single overall consequence can be convenient, but it can hide how that label was obtained. Conversely, the most severe term across every transcript may come from a model that is not the representative coding transcript. Reviewing both views prevents a misleading impression that one summary is the only valid molecular description.</p></section>'''
body+='<section id="basics"><h2>2. Reading the terminology</h2>'+table(['Term','Meaning in this project'],[['Variant / allele','One specified reference-to-alternate DNA change at a location. Different alternate bases at the same position are different alleles.'],['Reference / GRCh38','The genome sequence and coordinate system used to describe and check each input change. Coordinates cannot be mixed across builds.'],['SNV','A single-nucleotide variant: one reference base is replaced by another.'],['Indel','An insertion or deletion. This project includes small sequence alleles with REF and ALT lengths at most 50 bases.'],['Gene / transcript','A gene is a genomic locus; a transcript is one RNA version of that gene. One allele may affect several transcripts and more than one gene.'],['Consequence','A provider annotation describing the predicted molecular relationship between an allele and a feature or transcript.'],['MANE Select / canonical','Provider flags used here to choose a consistent representative transcript. Neither flag establishes clinical significance.'],['HGVS','Standardized change notation: c. refers to coding transcript coordinates, n. to noncoding transcript coordinates, and p. to protein coordinates. For example, p.Gly50Ala predicts glycine replaced by alanine at protein position 50. Missing notation stays missing.'],['NMD','Nonsense-mediated decay, a cellular RNA-surveillance process. An NMD transcript annotation identifies that transcript context; it does not by itself prove this allele causes RNA decay.'],['High-confidence BED','Intervals from the benchmark release identifying the genomic scope used for eligibility and coverage denominators.'],['ClinVar','A source of submitted variant assertions, with review status, conditions and possible conflicts. This report preserves dated source assertions.']])+'<p><strong>Example:</strong> one allele with 45 transcript rows is still one DNA change, not 45 people or 45 independent variants. An allele–gene pair is the unit used when comparing a representative transcript with other transcripts for the same gene.</p></section>'
body+='''<section id="validation"><h2>3. Training validation: establishing the baseline</h2><p>The first phase implemented the end-to-end workflow on five exact public chromosome 9 examples from the Ensembl training walkthrough. The source order, IDs and anchored deletion were preserved in an eight-column VCF. Every complete REF interval was checked against the official GRCh38 sequence, including both bases of the anchored <code>TA → T</code> deletion.</p>'''
p1rows=list(csv.DictReader((BASELINE/'results/variant-summary.tsv').open(),delimiter='\t'))
body+=table(['Training ID','Submitted GRCh38 change','Transcript rows','Provider most-severe term'],[[r['variant_id'],f"9:{pos} {ref} → {alt}",r['transcript_rows'],r['provider_most_severe']] for r,(_,pos,ref,alt) in zip(p1rows,[('var1',128328460,'TA','T'),('var2',128322349,'C','A'),('var3',128323079,'C','G'),('var4',128322917,'G','A'),('var5',128203516,'C','A')])])
body+='''<p>The five variants produced 216 transcript rows. Two COQ4 examples on MANE Select transcript <code>ENST00000300452.8</code> established a clear contrast: var3 had a missense annotation (<code>c.134C&gt;G; p.Ser45Cys</code>), whereas var1 was intronic (<code>c.402+2580del</code>). The deletion’s normalized representation was reconciled with the submitted anchored VCF record rather than treated as a different variant.</p><p><strong>What this established:</strong> authentic annotation, identity reconciliation independent of response order, traceable transcript cases, deterministic offline report rebuilding and explicit separation of clinical follow-up from annotation. Five baseline tests and regression verification passed. The teaching inputs and their totals remain separate from HG002 throughout HG002 analysis.</p></section>'''
body+='''<section id="methods"><h2>4. HG002 analysis: process and quality control</h2><h3>4.1 Define the scope before looking at consequences</h3><p>The fixed interval was GRCh38 chr9:128,000,001–129,000,000, a contiguous 1 Mb region surrounding the Training validation teaching region. It was recorded before examining HG002 annotation consequences. This is a purposeful pilot interval, not a random genomic sample. Therefore its spectrum is descriptive of this interval and benchmark sample.</p><p>The callset was pinned to GIAB HG002 NIST v4.2.1 GRCh38, together with its matching <code>benchmark_noinconsistent.bed</code>. Tabix/HTSlib indexed extraction retrieved the interval while preserving the original VCF header and records. A full remote VCF download and full-file checksum are not claimed; acquired slices and indexes have their own SHA-256 hashes.</p><h3>4.2 Establish an unambiguous allele identity</h3><p>Multiallelic records were split into individual ALT alleles present in the HG002 sample genotype. Source IDs, original ALT indexes, coordinates and complete records were retained. Chromosome naming was reconciled from <code>chr9</code> to <code>9</code> for Ensembl and reference compatibility. Symbolic alleles, breakends, spanning-deletion stars, unsupported sequence and alleles over 50 bases were outside the declared eligibility rules.</p><p>Each included reference allele was compared with the full forward-strand GRCh38 REF interval. Normalization used pysam 0.23.3 and embedded bcftools 1.21 with the official Ensembl release 116 chromosome 9 FASTA. Indels were trimmed and left-aligned against that sequence. Deduplication used chromosome, normalized position, REF and ALT together; sharing a coordinate alone was insufficient.</p><h3>4.3 Handle coordinates and boundaries consistently</h3><p>VCF positions are 1-based. BED and internal bin intervals are 0-based, half-open. A VCF record’s anchored REF span is <code>[POS−1, POS−1+length(REF))</code>. That complete span had to lie inside the chosen interval and a merged high-confidence BED region, both before and after normalization. An insertion is assigned using its reference anchor. A shifted allele falling outside those rules would be explicitly excluded.</p><h3>4.4 Acquire authentic annotations safely</h3><p>VEP REST requests used batches of no more than 100 alleles, with HGVS, MANE, canonical flags and transcript versions requested and all returned transcripts retained. There were 14 bounded batches, restricted to this pilot. Exact requests, untouched response bytes, timestamps, hashes, engine/service metadata where reported and input/reference/settings fingerprints were saved.</p><p>Response matching used verified echoed identity and normalized locus/allele representation, not array order. Missing, duplicate, unmatched or incorrect-build responses fail validation. Chunks resume only with matching fingerprints and raw hashes. A complete successful snapshot is promoted only after all inputs reconcile; the previous snapshot remains usable when acquisition fails. The database release was 116; a separate VEP engine version was not reported.</p>'''
qc=read(ROOT/'cache/prepare-qc.json')
body+=table(['Processing gate','Observed count','Interpretation'],[['Original records',1394,'One VCF record can contain more than one ALT allele.'],['ALT alleles after splitting',1417,'Allele-level ingestion count, before high-confidence filtering.'],['Excluded outside high confidence',110,'Explicit eligibility exclusions, not annotation failures.'],['REF-matched before normalization',1307,'All included complete REF intervals matched GRCh38.'],['Normalized eligible alleles',1307,'No additional boundary exclusion and no normalized duplicates in this run.'],['VEP response objects',1307,'Every eligible input was accounted for.'],['Transcript evidence rows',38589,'Only transcript feature annotations enter this count.'],['Valid results with no transcript overlap',22,'Retained as valid annotated alleles; not silently dropped.']],caption='Processing totals reconcile from ingestion through final transcript export.')
body+='''<h3>4.5 Compare transcript selection fairly</h3><p>A representative was selected separately for every allele–gene pair with transcript rows: applicable MANE Select first, then canonical, then deterministic accession order. Ties at the preferred tier were counted and resolved deterministically. Consequence sets were compared regardless of term order. A “missed more-severe term” means another transcript of that same gene has a higher-ranked molecular term than the representative, using the pinned Ensembl 116 ranking.</p><p>Regulatory, motif and intergenic annotations were retained separately, rather than accidentally counted as transcript rows. Blank optional values mean “not reported”; no missing HGVS, gene symbol or transcript flag was invented.</p></section>'''
body+='<section id="results"><h2>5. Expanded results and their meaning</h2><h3>5.1 How much data was actually analyzed?</h3>'
body+=f'<p>The final expanded run contains <strong>{n(m["input_alleles"])} distinct alleles</strong>: {n(m["variant_types"]["SNV"])} single-base substitutions and {n(m["variant_types"]["indel"])} indels. All have valid VEP response objects. There are {n(m["transcript_rows"])} transcript rows, and {n(m["no_transcript_alleles"])} alleles have no transcript overlap in the returned output. These counts measure different units and must not be interchanged.</p>'
body+='<h3>5.2 What kinds of consequences were reported?</h3>'+spectrum_fig
body+=f'<p>The largest provider-summary category is <code>intron_variant</code>, with {n(allele_counts["intron_variant"])} alleles. The run also includes {allele_counts["missense_variant"]} missense summaries, {allele_counts["synonymous_variant"]} synonymous summaries, {allele_counts["frameshift_variant"]} frameshift summary and {allele_counts["inframe_deletion"]} in-frame deletion summary. A rare severe-sounding molecular term is an annotation to examine, not a project diagnosis.</p>'
body+='''<p><strong>Why this matters:</strong> the spectrum describes how supplied benchmark alleles relate to the current gene models. It does not estimate disease prevalence, the frequency of these alleles in a population, or the accuracy of the original variant calls. A provider summary is computed across features; the selected transcript can legitimately have a different term.</p><h3>5.3 How sensitive are results to transcript choice?</h3>'''+sensitivity_fig
body+=f'<p>Consequence sets differ across transcripts in <strong>{n(m["pairs_differing"])} of {n(m["allele_gene_pairs"])} pairs ({pct(m["pairs_differing"],m["allele_gene_pairs"])})</strong>. In {n(m["pairs_selected_misses_more_severe"])} pairs ({pct(m["pairs_selected_misses_more_severe"],m["allele_gene_pairs"])}), the representative omits a more severe same-gene term found elsewhere. These percentages are strictly within-run annotation comparisons, not population estimates.</p>'
body+=table(['Selection issue','Count','Meaning'],[['Accession-order fallback',126,'Neither a usable MANE Select nor canonical flag selected the representative at the preferred reporting tier.'],['Ties at the preferred tier',97,'More than one candidate existed; deterministic tie resolution was required.'],['Different transcript consequences',1081,'The annotations are not reducible to a unique consequence set without losing transcript context.'],['Representative omits a more severe term',183,'Review the alternative transcript’s biotype, structure and relevance rather than assuming either label is the clinical answer.']])
body+='''<p><strong>Practical interpretation:</strong> representatives support consistent reporting, but the full evidence remains necessary. The SPTAN1 case below demonstrates why a splice-related term on an alternative transcript should be read alongside the intronic annotation on the MANE representative.</p><h3>5.4 Where do variants occur in the interval?</h3>'''+distribution_fig
body+=f'<p>The interval contains {n(m["high_confidence_bases"])} high-confidence bases out of 1,000,000. Counts are aggregated into forty fixed 25 kb windows. Unequal coverage means raw bin counts alone do not describe equal amounts of assessed sequence. Rates therefore use each bin’s clipped high-confidence bases. No zero-coverage window would receive a calculated zero-variant rate.</p><p><strong>Why this matters:</strong> a bar can be low because fewer supplied alleles occur there, because the callable benchmark coverage differs, or both. These are descriptive observations from one selected interval; no disease-hotspot or regional-selection claim is made.</p><h3>5.5 What information is missing?</h3>'
body+=table(['Optional transcript field','Rows without a reported value','Denominator'],[[k,n(v),n(m['transcript_rows'])+' transcript rows'] for k,v in m['missing_optional_transcript_fields'].items()])
body+='''<p>Absent MANE Select is not proof that a gene has no MANE transcript. HGVS can be absent for a feature relationship where a transcript-relative change is not returned. Missingness is reported explicitly so readers do not mistake a blank field for negative clinical evidence.</p></section>'''
body+='<section id="three-dimensional"><h2>5.6 A three-dimensional view of the same evidence</h2><p>The following figures add a spatial view of the result: position along chromosome 9 runs from left to right, consequence groups are arranged in rows, and bar height shows the number of alleles. They are count visualizations, not 3D models of DNA or proteins. The PDF figures are static; rotation and allele selection remain available in the local browser explorer.</p><p>The complete 3D overview is shown as Figure 1 near the front of this report. The following guidance explains that figure and provides a labelled close-up.</p>'
body+='<h3>How to read the overview</h3><p>Start with the X axis to locate a 25 kb region, choose a consequence row on Y, then read its bar height on Z. A taller bar means more observed benchmark alleles in that region/class. It does not mean greater disease risk. Several small coding or splice-related bars can be obscured by larger intronic counts, which is why the 2D spectrum, exact tables and a labelled close-up are supplied alongside the 3D view.</p>'+table(['Displayed class','Alleles in the full pilot'],collections.Counter(a['consequence_class'] for a in data['alleles']).most_common())
body+='<h3>A labelled close-up</h3><p>This four-window view makes small categories easier to inspect. The region contains two of the traced case-study loci, but the bars count all eligible alleles in those windows; a bar cannot be interpreted as the case allele alone.</p>'+zoom_3d+'<p><strong>What to take away:</strong> the full overview shows the joint pattern of location, consequence class and count; the close-up reveals small categories at a more readable scale. Both are derived from the same saved exports. Use the exact case evidence to interpret a particular allele.</p></section>'
body+='<section id="cases"><h2>6. Four cases explained</h2><p>Cases were selected to illustrate a coding SNV, a coding indel, transcript sensitivity and missing evidence. They are pedagogic examples, not an unbiased estimate of clinical categories. Source rows and alternative models are preserved below.</p></section>'
interpretations=[('A protein change is not automatically a disease-causing change.','The representative COQ4 transcript predicts a glycine-to-alanine change at protein position 50. The alternative shown adds an NMD-related transcript context but retains the same missense term. This demonstrates that consequence sets can differ even when the central amino-acid prediction agrees. The dated ClinVar entry reports Benign/Likely_benign; this is a submitted source summary, not a new project classification.'),('A deletion can change its annotation when the transcript changes.','The normalized GCCT → G allele deletes three bases after the VCF anchor. On the representative GOLGA2 coding transcript it is an in-frame deletion with predicted p.Glu742del. On the alternative shown, the same genomic allele lies in a 3′ untranslated region of an NMD transcript. ClinVar preserves conflicting classifications, including uncertain-significance and benign assertions; that disagreement should remain visible rather than being flattened into a single invented interpretation.'),('A high-ranked alternative term may describe a different transcript model.','The MANE Select SPTAN1 transcript places the allele in an intron, c.6763-109A>G. Another SPTAN1 transcript reports a splice-acceptor/noncoding consequence, n.78-2A>G, and has biotype protein_coding_CDS_not_defined. This is why “more severe” in an annotation ranking does not establish a clinically more relevant model. The dated ClinVar source summary is Benign with a single-submitter review status; clinical interpretation still depends on the full context.'),('Missing evidence should remain missing.','This downstream annotation refers to a long noncoding RNA transcript. A stable gene accession is present, but no gene symbol or representative HGVSc/HGVSp was returned. The report preserves the identifiers and missing fields rather than guessing a familiar gene name or manufacturing HGVS. There is no exact eligible ClinVar match in the fixed release; that is not evidence that the allele is benign.')]
for i,(case,(title,interpretation)) in enumerate(zip(cases,interpretations),1):
 a=case['allele'];r=case['selected'];alt=case['alternative'];sel=case['selection']
 body+=f'<section class="case-page"><p class="eyebrow">Case {i} · {e(case["label"])}</p><h2>{e(title)}</h2><p>{e(interpretation)}</p>'
 fields=[['Normalized GRCh38 allele',a['allele_id']],['Overall provider summary',a['provider_most_severe']],['Selected gene',r['gene_symbol'] or r['gene_id']],['Selected gene ID',r['gene_id']],['Selected transcript / biotype',r['transcript_id']+' / '+r['biotype']],['Selected exact consequences',r['consequence_terms']],['Selected HGVSc',r['hgvsc']],['Selected HGVSp',r['hgvsp']],['Why selected',sel['selection_tier']],['Selected source row',r['row_id']]]
 if alt:fields.extend([['Alternative transcript / biotype',alt['transcript_id']+' / '+alt['biotype']],['Alternative exact consequences',alt['consequence_terms']],['Alternative HGVSc',alt['hgvsc']],['Alternative HGVSp',alt['hgvsp']],['Alternative source row',alt['row_id']]])
 else:fields.append(['Alternative comparison','No different same-gene transcript consequence available for this case.'])
 body+=table(['Evidence field','Observed source value'],fields)
 for h in case['clinvar_matches']:
  body+='<h3>Dated source assertion — ClinVar 2026-11-08</h3>'+table(['Field','Source value'],[['Variation ID',h['clinvar_variation_id']],['Classification summary',h['classification_summary']],['Review status',h['review_status']],['Conditions',h['conditions']],['Conflict detail',h['conflicting_classifications']]])+f'<p><a href="{e(h["url"])}">ClinVar Variation {e(h["clinvar_variation_id"])}</a>. This live link may show newer information; the values above refer to the fixed release.</p>'
 if not case['clinvar_matches']:body+='<p>No exact eligible match in the dated ClinVar release. No classification is inferred.</p>'
 body+='<p class="callout"><strong>Evidence still needed for clinical assessment:</strong> condition- and allele-matched assertions with review status; appropriate population frequency; gene–disease validity and inheritance; phenotype fit; functional and segregation evidence. A molecular prediction or isolated source summary does not replace that review.</p></section>'
body+='''<section id="clinical"><h2>7. Dated clinical evidence overlay</h2><p>The overlay uses the fixed ClinVar GRCh38 release dated 8 November 2026. All chromosome 9 records were queried by index to avoid relying on a small padded interval that might miss equivalent indel representations. The extract contained 204,568 records/ALT alleles; 326 were outside the declared sequence/50-base eligibility. Eligible alleles were reference-checked and normalized with the same tool and reference as HG002 before exact matching.</p><p>There were 116 exact matched HG002 alleles and 1,191 without an exact eligible match. Each match retained Variation ID, source classification summary, review status, condition names/identifiers, conflicts, original record and source link. Coordinate-only VEP co-location identifiers were not used as substitutes for exact matching.</p><h3>What the matched records actually say</h3>'''
body+=table(['Exact source classification summary','Matched records'],class_counts.most_common(),caption='Categories are copied from the fixed source and are not project-assigned classifications.')
body+=table(['Exact source review-status string','Matched records'],review_counts.most_common())
body+='''<p><strong>How to read this:</strong> a match means the normalized allele identity is shared with an eligible source record. It does not mean the source assertion applies to every disease or phenotype, is current today, or has the same review strength as another entry. “No match” means no eligible exact entry in this fixed release/extract, not absence from every representation or evidence of benignity.</p><p>All matched source records were independently re-normalized during verification, and Variation IDs plus promoted classification, review and condition fields were checked against the original records. No new population-frequency enrichment, phenotype analysis or disease-specific curation was performed, even where source INFO contains additional fields.</p></section>'''
body+='''<section id="software"><h2>8. Software, explorer and reproducibility</h2><h3>Separate acquisition from offline analysis</h3><p>The project uses small Python entry points. Network acquisition is separate from reference validation, normalization, analysis and report generation. Normal report rebuilding uses a saved authentic snapshot and makes no network requests. JSON/TSV schemas document units, missingness, stable identities and the relationship between selected rows and raw output.</p><p>Training validation uses Python standard-library tooling. HG002 analysis pins pysam 0.23.3, with embedded bcftools/HTSlib 1.21. The optional 3D component bundles Three.js 0.180.0 and its MIT licence locally. The shareable HTML report embeds its styling and vector figures, so it can be copied independently of the project folder and opened without a server.</p><h3>A simpler explorer for readers</h3><p>The revised explorer defaults to an exact 2D position/count view. Selecting a type or consequence updates the view immediately; gene text updates live. A “What changed?” explanation identifies active filters and excluded alleles. A fixed count scale keeps filtered views comparable. The user then selects a 25 kb region and one allele, with plain-language consequence guidance before expandable transcript evidence. 3D remains optional, with a single restrained bar colour and a selected-region highlight rather than a rainbow that might imply clinical risk.</p><p>Filters only change the displayed subset of the saved experiment. They do not rerun VEP or alter the underlying result. Gene filtering is case-insensitive and accepts partial symbols or stable IDs. Consequence filtering uses the overall provider summary; individual transcript consequences remain visible as a separate concept.</p><h3>Quality checks performed</h3>'''
body+=table(['Check','Evidence and scope'],[['Baseline regression','Five Training validation tests and saved case identities; five inputs and 216 transcript rows reproduced.'],['HG002 analysis pipeline tests','Eleven tests including production multiallelic splitting/genotypes/provenance, REF failures, left alignment, interval edges, same-position different alleles, missing transcripts, selection and totals.'],['Saved scientific output','Input/response identity, REF checks, raw/export hashes, bin totals, high-confidence denominators and case rows reconciled.'],['Clinical overlap','Every matched clinical record re-normalized and promoted assertion fields checked against source.'],['Determinism','Complete analytical rebuild with networking disabled reproduced export hashes; repeated HTML rendering is deterministic from the snapshot.'],['Browser acceptance','Desktop and 390 px mobile controls, selections, reset, keyboard flow, reduced motion, actual WebGL failure and no remote runtime resource dependencies.'],['Visual review','Screenshots and print output reviewed; no claim of a formal screen-reader or comprehensive accessibility audit.']])
body+='''<h3>Observed resources</h3><p>The local machine is Apple Silicon arm64, with 8 logical CPUs and 8 GiB RAM. Preparation took approximately 0.21 seconds and 97 MB process peak RSS, excluding downloads. The 14 sequential REST batches took approximately 440 seconds. These are measured pilot observations; remote-service acquisition time is not a predictor of offline chromosome annotation throughput.</p><h3>Reproduce the saved analysis</h3><pre>python3 validation/run.py verify
analysis/.venv/bin/python analysis/pipeline.py analyze
analysis/.venv/bin/python analysis/pipeline.py render
analysis/.venv/bin/python analysis/pipeline.py verify
analysis/.venv/bin/python -m unittest discover -s analysis/tests -v</pre><p>Install the pinned HG002 analysis requirements first in a local virtual environment. To reacquire public data, use the separately documented <code>acquire</code>, <code>prepare</code>, <code>annotate</code> and ClinVar commands in the project README. A future service release can change annotations; the recorded snapshot is the reproducible basis for these results.</p></section>'''
body+='''<section id="limits"><h2>9. Limitations and work not completed</h2><ul><li><strong>Coverage:</strong> this is one preselected 1 Mb benchmark interval. It is neither whole-chromosome coverage nor a random genomic or population sample.</li><li><strong>Offline chromosome annotation:</strong> not executed. The standard Ensembl 116 GRCh38 cache archive is 27,644,657,162 bytes compressed, exceeding initially available approximately 22 GiB before extraction and other storage. Docker’s daemon was unavailable, and no local VEP/cache was found.</li><li><strong>Architecture:</strong> published release_116.0 images support linux/arm64 and linux/amd64. Architecture compatibility is available; storage and the operational engine/cache setup are the blockers.</li><li><strong>Backend completeness:</strong> a full offline JSON Lines adapter, chromosome chunking/resume path and corresponding verification remain to be implemented after infrastructure is provisioned. The completed REST pipeline is deliberately bounded.</li><li><strong>Release metadata:</strong> Ensembl database release 116 was reported; a separate VEP engine version was not.</li><li><strong>Clinical evidence:</strong> the overlay is dated and retains source assertions. No formal clinical classification, patient outcome, diagnosis or comprehensive disease-specific interpretation is supplied.</li><li><strong>Transcript models:</strong> differing annotations reflect current transcript structures/biotypes. A severe term on one alternative model is not proof that model is the most clinically relevant.</li><li><strong>Performance and validation:</strong> timings are local observations. Browser checks are not a formal performance study or complete accessibility certification.</li><li><strong>Rights and publication:</strong> data remain local. No GitHub push or deployment was performed. Upstream and third-party reuse terms must be reviewed before distributing raw snapshots or source datasets; no code licence is applied to them.</li></ul><p>The HTML and PDF are explanatory summaries prepared for sharing. They contain selected observed results and source citations, rather than the complete benchmark or raw VEP/ClinVar datasets. This report does not claim NHS affiliation or clinical endorsement.</p></section>'''
body+='<section id="future"><h2>10. Future work and decision gates</h2>'+table(['Extension','Required work before proceeding','Evidence of success'],[['Whole chromosome 9','Provision storage and an operational compatible engine, matching cache/reference, and pinned offline adapter. Implement bounded/resumable chunks and measure pilot throughput.','All eligible chromosome alleles accounted for; REF/QC and transcript totals reconciled; measured runtime, memory and disk reported.'],['Whole genome','Scale only after chromosome resource measurements. Parallelize by chromosome with independent fingerprints and QC.','Consistent assembly, releases and eligibility across chromosomes; no silent omissions or scope inflation.'],['Additional public samples','Use matching releases, shared high-confidence intervals and the same annotation/selection rules.','Sample-specific comparisons with explicit denominators; population claims require a properly designed cohort.'],['Formal calling benchmark','Add an independent query callset and matched truth VCF/BED; use a representation-aware comparator and stratifications.','Precision/recall with documented query, truth, region and representation handling; annotation totals are not benchmark accuracy.'],['Disease-specific evidence','Curate allele-matched assertions, review status/conflicts, appropriate population frequencies, gene–disease validity, phenotype and functional/segregation data.','Condition-specific evidence provenance and unresolved disagreements preserved; qualified clinical assessment kept separate from annotation.'],['Release drift','Re-annotate a fixed sentinel panel using separately pinned releases and audit transcript changes.','Traceable differences attributed to source release or pipeline changes, with regression cases retained.'],['Reader usability','Observe readers completing filter, region and allele-selection tasks; test additional browsers and assistive technologies.','Users can explain what changed, what the units mean, and why a molecular consequence is not a clinical conclusion.']])+'</section>'
body+='''<section id="conclusion"><h2>11. Conclusions</h2><p>The completed work establishes an auditable annotation workflow from five training examples to 1,307 HG002 alleles in a fixed benchmark interval. It demonstrates, with authentic output, that transcript context materially changes the molecular annotation for many allele–gene pairs. A representative transcript is useful for consistent reporting, but its result should remain linked to the other transcript evidence.</p><p>The experiment also demonstrates the value of exact allele matching, explicit coverage and missingness, and saved source provenance. The ClinVar overlap provides dated assertions for review without converting predictions into diagnoses. The appropriate next analytical step is provisioned offline scaling with the same QC discipline; the appropriate next interpretive step is scoped, condition-specific evidence review.</p></section>'''
body+='<section id="appendix"><h2>Appendix: numerical evidence and provenance</h2><h3>A. Complete allele spectrum by variant type</h3>'+table(['Provider most-severe term','SNVs','Indels','Total'],[[t,next((r['count'] for r in spectrum if r['unit']=='alleles' and r['variant_type']=='SNV' and r['term']==t),0),next((r['count'] for r in spectrum if r['unit']=='alleles' and r['variant_type']=='indel' and r['term']==t),0),v] for t,v in allele_counts.most_common()])
body+='<h3>B. Transcript-selection tiers</h3>'+table(['Selection tier','Allele–gene pairs'],tier_counts.most_common())
body+='<h3>C. Complete transcript-level most-severe spectrum</h3><p>One category per transcript row, denominator 38,589. The separate multi-term export allows a row to contribute to several terms and is not summed here.</p>'+table(['Most-severe transcript term','Transcript rows'],[[r['term'],r['count']] for r in spectrum if r['unit']=='transcript_rows'])
body+='<h3>D. Evidence files retained with the project</h3>'+table(['Artifact','Purpose'],[['training-variants.grch38.vcf / Training validation snapshot','Exact teaching inputs and authentic baseline response.'],['original-region.vcf / origin-map.tsv','Original HG002 record and ALT-index provenance.'],['normalized.vcf / exclusions.tsv','Annotation inputs and inspectable eligibility exclusions.'],['allele-summary.tsv / transcripts.tsv','Complete allele and transcript evidence.'],['transcript-selection.tsv / gene-summary.tsv','Per-pair selections, alternatives and gene aggregates.'],['consequence-spectrum.tsv / transcript-term-counts.tsv','Explicit allele and transcript denominators.'],['bins.tsv / high-confidence.bed','Fixed windows and coverage evidence.'],['clinvar-matches.tsv / clinvar-overlay.json','Dated exact matches, source assertions and unmatched counts.'],['snapshot.json / run-manifest.json / export-manifest.json','Requests/chunks, release/settings/reference provenance and hashes.'],['verification.json / browser-verification.json','Scientific reconciliation and browser acceptance records.']])
body+='<h3>E. Selected snapshot fingerprints</h3>'+table(['Item','SHA-256 or reported value'],[['Normalized annotation VCF',snap['preparation']['normalized_vcf_sha256']],['GRCh38 chromosome 9 FASTA',snap['preparation']['reference_sha256']],['Acquired original HG002 regional VCF',snap['preparation']['sources']['sha256']['region.original.vcf']],['Acquired high-confidence BED',snap['preparation']['sources']['sha256']['benchmark.bed']],['Acquired ClinVar chromosome 9 extract',clinical['source']['source_region_sha256']],['Last VEP chunk acquired (UTC)',snap['acquired_utc']],['Database release',116],['Specific VEP engine version','Not reported']])+'</section>'
sources=[('Ensembl training walkthrough','https://training.ensembl.org/text_module/human_vep_walkthrough'),('NIST Genome in a Bottle','https://www.nist.gov/programs-projects/genome-bottle'),('Fixed HG002 NIST v4.2.1 GRCh38 benchmark VCF',snap['preparation']['sources']['sources']['vcf']),('Matching high-confidence BED',snap['preparation']['sources']['sources']['bed']),('Official GRCh38 chromosome 9 reference',snap['preparation']['sources']['sources']['reference']),('Ensembl REST batch VEP documentation','https://rest.ensembl.org/documentation/info/vep_region_post'),('Pinned Ensembl 116 consequence definitions','https://github.com/Ensembl/ensembl-variation/blob/release/116/modules/Bio/EnsEMBL/Variation/Utils/Constants.pm'),('Dated ClinVar GRCh38 release 2026-11-08',clinical['source']['url']),('ClinVar download documentation','https://www.ncbi.nlm.nih.gov/clinvar/docs/downloads/'),('Variant interpretation educational context','https://www.genomicseducation.hee.nhs.uk/education/taught-courses/variant-interpretation/'),('Ensembl reuse terms','https://www.ensembl.org/info/about/legal/disclaimer.html')]
body+='<section id="sources"><h2>Sources</h2><p>Results refer to the saved acquisition and dated releases above. External links are references, not runtime dependencies; live pages may change.</p><ol>'+''.join(f'<li><a href="{e(url)}">{e(label)}</a><br><span class="source-url">{e(url)}</span></li>' for label,url in sources)+'</ol><p class="small">Report figures are generated from the saved experimental exports using Matplotlib. No simulated annotation values or invented clinical classifications are used. The complete evidence exports remain in the local project; this report is a portable explanatory account.</p></section>'
